('q911-20261118-Evaluation_Acquis_VTC','Modèle d’évaluation des acquis VTC','Word existant ouvert et texte lu le 18/11/2026. Critères et niveaux d’acquisition prévus. Modèle vierge : ne démontre aucune évaluation réalisée ni réussite.',NULL,NULL,'https://gestion.ftransport.fr/cours/vtc/Evaluation_Acquis_VTC.docx','{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "sha256": "b1824c846f3348ede0e886fb2eff5a3fef8ec0b84963d63fbeab37939bfd4f62", "verification": "structure DOCX et texte lus", "piece_jointe": false}'::jsonb,'[11]'::jsonb),
('q911-20261118-Evaluation_Acquis_TAXI','Modèle d’évaluation des acquis TAXI','Word existant ouvert et texte lu le 18/11/2026. Critères et niveaux d’acquisition prévus. Modèle vierge : ne démontre aucune évaluation réalisée ni réussite.',NULL,NULL,'https://gestion.ftransport.fr/cours/vtc/Evaluation_Acquis_TAXI.docx','{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "sha256": "caebe99f44aa9de1118694f496bc20e7cab37cdb57af7800cf6fabd2dc956957", "verification": "structure DOCX et texte lus", "piece_jointe": false}'::jsonb,'[11]'::jsonb),
('q911-20261118-module-1','Introduction présentiel et règlement intérieur','Contenu serveur : accueil, programme, épreuves et formulaire CGV/règlement intérieur (cours 102). Le règlement est un formulaire existant, pas un fichier inventé ; l’affichage ne prouve pas la lecture.','module_editor_state','1',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "présentiel VTC/TAXI"}'::jsonb,'[9]'::jsonb),
('q911-20261118-module-2','Cours et QUIZ VTC','Banque de questions effectivement enregistrée et inspectée, identifiants permanents et matières relevés. Dispositif d’entraînement/évaluation, pas preuve que chaque élève atteint les objectifs. Quiz : cours 2/10 ; le PDF et PowerPoint T3P Partie 1 communs ont été lus en session connectée (50 diapositives, empreintes conservées). Aucun autre support déclaré lu dans ce complément.','module_editor_state','2',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "VTC"}'::jsonb,'[10, 11]'::jsonb),
('q911-20261118-module-10','Cours et QUIZ TAXI','Banque de questions effectivement enregistrée et inspectée, identifiants permanents et matières relevés. Dispositif d’entraînement/évaluation, pas preuve que chaque élève atteint les objectifs. Quiz : cours 2/10 ; le PDF et PowerPoint T3P Partie 1 communs ont été lus en session connectée (50 diapositives, empreintes conservées). Aucun autre support déclaré lu dans ce complément.','module_editor_state','10',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "TAXI"}'::jsonb,'[10, 11]'::jsonb),
('q911-20261118-module-4','Bilan exercices VTC','Banque de questions effectivement enregistrée et inspectée, identifiants permanents et matières relevés. Dispositif d’entraînement/évaluation, pas preuve que chaque élève atteint les objectifs. Bilan exercices : projection actuelle des cours, JSON historique distinct ; aucune modification des questions ou copies.','module_editor_state','4',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "VTC"}'::jsonb,'[10, 11]'::jsonb),
('q911-20261118-module-9','Bilan exercices TAXI','Banque de questions effectivement enregistrée et inspectée, identifiants permanents et matières relevés. Dispositif d’entraînement/évaluation, pas preuve que chaque élève atteint les objectifs. Bilan exercices : projection actuelle des cours, JSON historique distinct ; aucune modification des questions ou copies.','module_editor_state','9',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "TAXI"}'::jsonb,'[10, 11]'::jsonb),
('q911-20261118-module-5','Bilan examen VTC','Banque de questions effectivement enregistrée et inspectée, identifiants permanents et matières relevés. Dispositif d’entraînement/évaluation, pas preuve que chaque élève atteint les objectifs. Nouveaux passages : version et remise via bilan_future_receipts/submissions. Banque seule ≠ passage réalisé.','module_editor_state','5',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "VTC"}'::jsonb,'[11]'::jsonb),
('q911-20261118-module-11','Bilan examen TAXI','Banque de questions effectivement enregistrée et inspectée, identifiants permanents et matières relevés. Dispositif d’entraînement/évaluation, pas preuve que chaque élève atteint les objectifs. Nouveaux passages : version et remise via bilan_future_receipts/submissions. Banque seule ≠ passage réalisé.','module_editor_state','11',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "module_id", "date_mise_a_jour_technique_pas_date_evaluation": true, "formation": "TAXI"}'::jsonb,'[11]'::jsonb),
('q911-20261118-ri-acceptation','Acceptation enregistrée CGV et règlement — exemple session novembre','Deux acceptations et signed_at 02/11/2026 16:53:23 UTC enregistrés. Inscription 70e60626-86da-4e1d-b0a2-7d17b7dafaf2 à session e8dee3f0-22bd-4187-ab61-41026b316e6c, VTC soir 02–13/11/2026. Acceptation le jour du début ; heure réelle de première prestation et version du règlement reçu non prouvées. Aucune image de signature dans ce document : ne pas le qualifier de signature manuscrite.','apprenant_documents_completes','0b880c08-1324-4b29-8103-8b9671bcac13',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "apprenant_id": "317750c9-5976-4fde-ad37-0de4a57d2ccb", "session_id": "e8dee3f0-22bd-4187-ab61-41026b316e6c", "evenement_le": "2026-11-02T16:53:23.308Z"}'::jsonb,'[9]'::jsonb),
('q911-20261118-suivi-module','Suivi individuel — bilan exercices module 4','Validation serveur du module 4 enregistrée le 16/11/2026 10:33:09 UTC (progression enregistrée 100 %). Dossier VTC, formation 02–15/11 ; inscription fdc31684-1966-4744-a819-077d8fc41724 à session 91f00853-2ac2-4da6-996b-4832fc132b6b du 02–13/11. Validation postérieure à la session et à la fin CRM : conserver ce constat, sans déplacer la date. Preuve de suivi enregistré seulement, ni adaptation effective ni acquisition globale.','apprenant_module_completion','54381715-f005-4d06-afe7-7d281f1fd9d9',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "apprenant_id": "18d7f8fb-613d-439b-a793-c56c56817818", "session_id": "91f00853-2ac2-4da6-996b-4832fc132b6b", "evenement_le": "2026-11-16T10:33:09.363764Z"}'::jsonb,'[10]'::jsonb),
('q911-20261118-revision','Quiz de révision des questions fausses — réalisation enregistrée','Révision questions fausses EB5 terminée le 17/11/2026 08:55:31 UTC ; score brut enregistré 29/45, sans recalcul ni modification. Cela démontre une activité de remédiation enregistrée, pas une décision de formateur ni une adaptation personnalisée attestée. Session à vérifier ; ancienne tentative, réponses et corrigé officiel non rapprochés dans ce contrôle : aucun verdict de réussite retenu.','apprenant_quiz_results','e62d8d12-a0a0-459b-b485-13dc42d33b1a',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "apprenant_id": "1a143496-f384-4143-acb9-9f81d4f1e942", "evenement_le": "2026-11-17T08:55:31.207093Z", "session": "non établie"}'::jsonb,'[10, 11]'::jsonb),
('q911-20261118-bilan-remis','Bilan examen — remise versionnée réellement enregistrée','Bilan VTC module 5 exercice 504 remis le 17/11/2026 10:37:53 UTC, reçu 3628f37e-4294-4e5f-a036-26dde0b691fe et version 760abe32-3e72-4af5-b0c7-b906c58973ef. Compteurs conservés tels quels 106/194 : pas de note globale ni verdict inventé. Identité du propriétaire rapprochée du dossier VTC e-learning 050fec17-8b5a-4ae1-8a72-abf451de8885. Aucune session rattachée et dates de formation CRM absentes ; limite explicitement conservée. Réponses personnelles non copiées dans la preuve.','bilan_future_submissions','3628f37e-4294-4e5f-a036-26dde0b691fe',NULL,'{"controle_le": "2026-11-18", "statut_audit": "preuve existante avec limites, conformité non déclarée", "lookup": "receipt_id", "apprenant_id": "050fec17-8b5a-4ae1-8a72-abf451de8885", "version_id": "760abe32-3e72-4af5-b0c7-b906c58973ef", "evenement_le": "2026-11-17T10:37:53.487521Z", "session": "absente"}'::jsonb,'[11]'::jsonb)), enrichis AS (
 SELECT c.*, CASE WHEN c.source_table='module_editor_state' THEN
 c.meta || (SELECT jsonb_build_object('source_row_id',m.id,'module_id',m.module_id,'updated_at_technique',m.updated_at,'empreinte_md5',md5(m.module_data::text),'cours',jsonb_array_length(coalesce(m.module_data->'cours','[]'::jsonb)),'exercices',jsonb_array_length(coalesce(m.module_data->'exercices','[]'::jsonb))) FROM public.module_editor_state m WHERE m.module_id=c.source_id::integer)
 ELSE c.meta END metadata
 FROM candidats c
), ajouts AS (
 INSERT INTO public.qualiopi_preuves(ref_key,titre,description,ce_que_demontre,emplacement,source_libelle,source_type,source_table,source_id,lien_url,remarque_interne,fichiers,date_preuve)
 SELECT ref_key,titre,description,description,CASE WHEN lien_url IS NOT NULL THEN lien_url ELSE 'CRM / Cours et exercices : '||source_table||' / '||source_id END,'Vérification réelle du 18/11/2026 — référence, pas conformité','reference',source_table,CASE WHEN source_table='module_editor_state' THEN metadata->>'source_row_id' ELSE source_id END,lien_url,metadata::text,'[]'::jsonb,CASE WHEN metadata ? 'evenement_le' THEN ((metadata->>'evenement_le')::timestamptz AT TIME ZONE 'Europe/Paris')::date ELSE NULL END
 FROM enrichis WHERE metadata IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM public.qualiopi_preuves old WHERE old.ref_key=enrichis.ref_key) RETURNING id,ref_key
), ids AS (
 SELECT id,ref_key FROM ajouts UNION ALL SELECT p.id,p.ref_key FROM public.qualiopi_preuves p JOIN candidats c USING(ref_key)
), liens AS (
 INSERT INTO public.qualiopi_preuve_liens(preuve_id,indicateur,justification)
 SELECT i.id,j.value::integer,'Référence vérifiée avec limites explicites ; ne vaut pas conformité ni réussite. Voir description.' FROM ids i JOIN candidats c USING(ref_key) CROSS JOIN LATERAL jsonb_array_elements_text(c.indicateurs) j
 WHERE NOT EXISTS(SELECT 1 FROM public.qualiopi_preuve_liens l WHERE l.preuve_id=i.id AND l.indicateur=j.value::integer)
 RETURNING indicateur
)
SELECT (SELECT count(*) FROM ajouts) preuves_ajoutees,(SELECT count(*) FROM liens) liens_ajoutes;
